304	fn install_post_commit_hook(repo_dir: &str) -> Result<()> {
305	    let git_dir = git_common_dir(repo_dir)?;
306	    let hook_path = git_dir.join("hooks").join("post-commit");
307	
308	    if hook_path.exists() {
309	        let content = fs::read_to_string(&hook_path)?;
310	        if content.contains(HOOK_MARKER) {
311	            println!("post-commit hook already contains gossamer indexing, skipping.");
312	            return Ok(());
