315	        writeln!(file, "{}", HOOK_SNIPPET)?;
316	    } else {
317	        fs::create_dir_all(hook_path.parent().unwrap())?;
318	        fs::write(&hook_path, format!("#!/bin/sh\n{}\n", HOOK_SNIPPET))?;
